/* Practical tools: personal budgets, exports, resumable drafts and a compact mobile dock. */
(()=>{
 const $=id=>document.getElementById(id);
 const tools=document.createElement('dialog');tools.id='workspaceTools';tools.className='personal-settings workspace-tools';tools.setAttribute('aria-labelledby','workspaceToolsTitle');tools.innerHTML='<div class="personal-settings-head"><span class="eyebrow">DV / IL TUO SPAZIO</span><button type="button" id="closeWorkspaceTools" aria-label="Chiudi strumenti">×</button></div><h2 id="workspaceToolsTitle">Tutto sotto controllo.</h2><p id="workspaceConnection" role="status"></p><div id="workspaceLoadState"></div><button type="button" id="refreshWorkspace" class="primary-button">Aggiorna i miei dati ↻</button><h3>Porta i tuoi dati con te.</h3><p>La copia JSON contiene calendario, percorso, rubrica, wishlist, spese, outfit e preferenze. I CSV si aprono in Excel. I file contengono i tuoi dati personali: scegli tu dove conservarli.</p><div class="workspace-export-actions"><button type="button" id="exportPersonalData">Scarica copia completa · JSON</button><button type="button" id="exportExpenses">Esporta spese · CSV</button><button type="button" id="exportWishes">Esporta wishlist · CSV</button></div><p id="workspaceExportStatus" role="status"></p><p class="workspace-small">La copia JSON è un’esportazione; il ripristino automatico non è incluso.</p>';document.body.append(tools);
 $('closeWorkspaceTools').onclick=()=>tools.close();
 function openTools(){if(!currentUser||!$('authOverlay').classList.contains('hidden'))return;$('cinemaMenu')?.close();tools.showModal();paintStatus()}
 for(const parent of [document.querySelector('.sidebar-bottom'),document.querySelector('.cinema-utilities')]){const b=document.createElement('button');b.type='button';b.className='owner-contact-trigger';b.textContent='Il mio spazio · dati e strumenti';b.onclick=openTools;parent?.append(b)}
 const labels={calendario:'Calendario',percorso:'Percorso',contatti:'Rubrica',wishlist:'Wishlist',spese:'Spese'};
 function paintStatus(){$('workspaceConnection').textContent=navigator.onLine?'Connessione di rete presente. Controlla sotto l’esito dell’ultimo caricamento.':'Sei offline. Puoi leggere i dati già disponibili e conservare una bozza su questo dispositivo; i salvataggi richiedono internet.';$('workspaceLoadState').replaceChildren();for(const [id,label] of Object.entries(labels)){const state=workspaceLoadState[id],row=document.createElement('p');row.className='workspace-status-row';const name=document.createElement('b');name.textContent=label;const note=document.createElement('span');note.textContent=state?.phase==='ok'?'Caricato · '+new Date(state.at).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'}):state?.phase==='error'?'Da ricaricare':state?.phase==='loading'?'Caricamento…':'Non ancora caricato';row.append(name,note);$('workspaceLoadState').append(row)}}
 addEventListener('workspace:load',paintStatus);addEventListener('online',()=>{paintStatus();toastInfo('Connessione ripristinata. Puoi riprovare i salvataggi.');});addEventListener('offline',()=>{paintStatus();toastInfo('Connessione assente: conserva la bozza e salva quando torni online.');});
 $('refreshWorkspace').onclick=async()=>{const b=$('refreshWorkspace');b.disabled=true;await Promise.allSettled([loadEvents(),loadCareer(),loadContacts(),loadWishlist(),loadExpenses()]);b.disabled=false;paintStatus()};
 async function exporting(button,fn){button.disabled=true;$('workspaceExportStatus').textContent='Preparazione della copia dal tuo account…';try{await fn();$('workspaceExportStatus').textContent='File preparato. Controlla i download del browser.'}catch(e){$('workspaceExportStatus').textContent=e.message||'Esportazione non riuscita. Riprova.'}finally{button.disabled=false}}
 $('exportPersonalData').onclick=e=>exporting(e.target,async()=>{const backup=await exportPersonalBackup();downloadWorkspaceFile('dv-copia-'+localCalendarDate()+'.json',JSON.stringify(backup,null,2),'application/json')});
 async function exportTable(kind,month){const user=await getCurrentUser();if(!user)throw Error('Accedi per esportare.');const request=kind==='spese'?expensesRequest:wishlistRequest;let rows=await fetchCompleteTable(request,user.id);if(currentUser?.id!==user.id)throw Error('L’account è cambiato.');if(month)rows=rows.filter(x=>x.expense_date?.startsWith(month));let csv;if(kind==='spese')csv=[['Data','Descrizione','Categoria','Importo EUR','Note'],...rows.map(x=>[x.expense_date,x.description,x.category,Number(x.amount).toFixed(2).replace('.',','),x.notes])];else csv=[['Prodotto','Negozio','Categoria','Prezzo','Valuta','Taglia','Colore','Priorità','Acquistato','Link','Note'],...rows.map(x=>{const d=wishlistDetails(x.notes);return [x.title,x.site_name,x.category,x.price??'',x.currency,d.size,d.color,d.priority,d.purchased?'Sì':'No',x.product_url,d.notes]})];downloadWorkspaceFile('dv-'+kind+'-'+(month||localCalendarDate())+'.csv',csvDocument(csv),'text/csv;charset=utf-8')}
 $('exportExpenses').onclick=e=>exporting(e.target,()=>exportTable('spese'));$('exportWishes').onclick=e=>exporting(e.target,()=>exportTable('wishlist'));
 // The monthly budget shares the visible expense month, independent of list filters.
 const budget=document.createElement('section');budget.className='monthly-budget';budget.setAttribute('aria-labelledby','budgetHeading');budget.innerHTML='<div><span class="eyebrow">IL MESE, SOTTO CONTROLLO</span><h2 id="budgetHeading">Il tuo budget.</h2><p id="budgetSummary"></p><progress id="budgetProgress" max="100" value="0" aria-label="Budget utilizzato"></progress></div><form id="budgetForm"><label for="budgetAmount">Budget del mese (€)</label><input id="budgetAmount" inputmode="decimal" placeholder="Es. 500,00"><div><button type="submit">Salva budget</button><button type="button" id="removeBudget">Rimuovi</button></div><p id="budgetMessage" role="status"></p></form>';$('spCatBreakdown').before(budget);
 let paintedMonth='';function paintBudget(){const key=speseMonthKey(speseViewDate),amount=cleanWorkspaceTools(currentUser?.user_metadata?.workspace_tools).budgets[key]||0;const snapshot=budgetSnapshot(expenseEntries,key,amount);$('budgetHeading').textContent='Budget · '+speseViewDate.toLocaleDateString('it-IT',{month:'long',year:'numeric'});$('budgetSummary').textContent=amount?(snapshot.remaining>=0?'Ti restano '+fmtEuro(snapshot.remaining/100)+' su '+fmtEuro(amount/100):'Hai superato il budget di '+fmtEuro(-snapshot.remaining/100)):'Scegli un limite per confrontarlo con tutte le spese di questo mese.';$('budgetProgress').value=snapshot.percent;$('budgetProgress').hidden=!amount;$('budgetProgress').setAttribute('aria-valuetext',amount?`${fmtEuro(snapshot.spent/100)} spesi su ${fmtEuro(amount/100)}`:'Budget non impostato');if(document.activeElement!==$('budgetAmount')||paintedMonth!==key)$('budgetAmount').value=amount?(amount/100).toFixed(2).replace('.',','):'';paintedMonth=key;}
 async function saveBudget(value){const key=speseMonthKey(speseViewDate);$('budgetMessage').textContent='Salvataggio…';try{await updateWorkspaceTools(data=>{if(value)data.budgets[key]=value;else delete data.budgets[key];return data});$('budgetMessage').textContent='Budget salvato nel tuo account.';paintBudget()}catch(e){$('budgetMessage').textContent=e.message}}
 $('budgetForm').onsubmit=async e=>{e.preventDefault();const cents=parseMoneyCents($('budgetAmount').value);if(!cents){$('budgetMessage').textContent='Inserisci un importo positivo valido.';return}const b=e.submitter;b.disabled=true;try{await saveBudget(cents)}finally{b.disabled=false}};$('removeBudget').onclick=async e=>{e.target.disabled=true;try{await saveBudget(0)}finally{e.target.disabled=false}};
 const filters=document.createElement('div');filters.className='expense-filters';filters.innerHTML='<label>Cerca spese<input id="spSearch" type="search" placeholder="Descrizione, categoria, note…"></label><label>Categoria<select id="spCategoryFilter"><option value="">Tutte</option></select></label><button type="button" id="exportExpenseMonth">CSV del mese ↗</button><small id="spFilterCount"></small>';$('spList').before(filters);for(const option of $('spCategory').options)filters.querySelector('select').append(new Option(option.text,option.value));filters.addEventListener('input',e=>{if(e.target.matches('input,select'))renderExpenses()});filters.addEventListener('change',e=>{if(e.target.matches('select'))renderExpenses()});$('exportExpenseMonth').onclick=async e=>{const b=e.target;b.disabled=true;try{await exportTable('spese',speseMonthKey(speseViewDate));toastSuccess('CSV del mese preparato.')}catch(error){toastError(error.message)}finally{b.disabled=false}};
 addEventListener('workspace:expenses',paintBudget);addEventListener('workspace:tools',paintBudget);addEventListener('personal:appearance',paintBudget);
 // Navigation dock: native buttons, no replacement of the browser's scrolling.
 const dock=document.createElement('nav');dock.className='workspace-dock';dock.setAttribute('aria-label','Accesso rapido mobile');for(const [module,label] of [['home','Home'],['calendario','Agenda'],['wishlist','Wishlist'],['calcio','Calcio']]){const b=document.createElement('button');b.type='button';b.dataset.dock=module;b.textContent=label;b.onclick=()=>showModule(module,{transition:true});dock.append(b)}const more=document.createElement('button');more.type='button';more.textContent='Menu';more.onclick=()=>window.dispatchEvent(new Event('director:menu'));dock.append(more);$('appShell').append(dock);addEventListener('workspace:module',e=>dock.querySelectorAll('[data-dock]').forEach(b=>{if(b.dataset.dock===e.detail)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')}));
 const authObserver=new MutationObserver(()=>{if(!$('authOverlay').classList.contains('hidden')){tools.close();$('spSearch').value='';$('spCategoryFilter').value='';$('workspaceExportStatus').textContent='';$('budgetAmount').value='';$('budgetMessage').textContent='';paintedMonth='';paintBudget()}});authObserver.observe($('authOverlay'),{attributes:true,attributeFilter:['class']});paintBudget();paintStatus();
})();
